  "content": "// Gradient text component for premium look on Sushasan website
import { addPropertyControls, ControlType } from "framer"
import type { CSSProperties } from "react"

interface GradientTextProps {
    text: string
    fromColor: string
    toColor: string
    angle: number
    font: CSSProperties
    style?: CSSProperties
}

/**
 * @framerSupportedLayoutWidth auto
 * @framerSupportedLayoutHeight auto
 */
export default function GradientText(props: GradientTextProps) {
    const {
        text = "Intelligence",
        fromColor = "#1e40af",
        toColor = "#ea8d0a",
        angle = 135,
        font,
        style,
    } = props

    const isFixedWidth = style && style.width === "100%"

    return (
        <span
            style={{
                ...style,
                ...(isFixedWidth ? {} : { minWidth: "max-content" }),
                ...font,
                background: `linear-gradient(${angle}deg, ${fromColor} 0%, ${toColor} 100%)`,
                WebkitBackgroundClip: "text",
                WebkitTextFillColor: "transparent",
                backgroundClip: "text",
                display: "inline-block",
                position: "relative",
            }}
        >
            {text}
        </span>
    )
}

addPropertyControls(GradientText, {
    text: {
        type: ControlType.String,
        title: "Text",
        defaultValue: "Intelligence",
        displayTextArea: true,
    },
    fromColor: {
        type: ControlType.Color,
        title: "From Color",
        defaultValue: "#1e40af",
    },
    toColor: {
        type: ControlType.Color,
        title: "To Color",
        defaultValue: "#ea8d0a",
    },
    angle: {
        type: ControlType.Number,
        title: "Angle",
        defaultValue: 135,
        min: 0,
        max: 360,
        step: 1,
        unit: "deg",
    },
    font: {
        type: ControlType.Font,
        title: "Font",
        controls: "extended",
        defaultFontType: "sans-serif",
        defaultValue: {
            fontSize: "72px",
            variant: "Bold",
            letterSpacing: "-0.02em",
            lineHeight: "1.1em",
        },
    },
})
",
  "exports": [
    {
